#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef enum { SUM_OK, SUM_EMPTY, SUM_RANGE, SUM_MEMORY } SumError;

typedef struct {
    int median;
    int mode;
    double mean;
} Summary;

static int compare_ints(const void *a, const void *b) {
    int x = *(const int *)a, y = *(const int *)b;
    return (x > y) - (x < y);
}

static SumError summarize(const int *values, int n, Summary *out) {
    int *sorted = malloc((size_t)(n > 0 ? n : 1) * sizeof *sorted);
    int *histogram = calloc(101, sizeof *histogram);
    if (sorted == NULL || histogram == NULL) {
        free(sorted);
        free(histogram);
        return SUM_MEMORY;
    }
    if (n == 0) {
        return SUM_EMPTY;
    }
    long long total = 0;
    for (int i = 0; i < n; i++) {
        if (values[i] < 0 || values[i] > 100) {
            return SUM_RANGE;
        }
        sorted[i] = values[i];
        histogram[values[i]]++;
        total += values[i];
    }
    qsort(sorted, (size_t)n, sizeof *sorted, compare_ints);
    int mode = 0;
    for (int v = 1; v <= 100; v++) {
        if (histogram[v] > histogram[mode]) {
            mode = v;
        }
    }
    out->median = sorted[(n - 1) / 2];
    out->mode = mode;
    out->mean = (double)total / n;
    free(histogram);
    free(sorted);
    return SUM_OK;
}

int main(void) {
    int n;
    while (scanf("%d", &n) == 1 && n >= 0 && n <= 100) {
        int values[100];
        for (int i = 0; i < n; i++) {
            if (scanf("%d", &values[i]) != 1) {
                return 0;
            }
        }
        Summary s;
        SumError e = summarize(values, n, &s);
        if (e == SUM_OK) {
            printf("медиана %d, мода %d, среднее %.2f\n", s.median, s.mode, s.mean);
        } else if (e == SUM_EMPTY) {
            printf("ошибка: пустая группа\n");
        } else if (e == SUM_RANGE) {
            printf("ошибка: оценка вне диапазона\n");
        } else {
            printf("ошибка: нет памяти\n");
            return 1;
        }
    }
    return 0;
}

