static SumError summarize(const int *values, int n, Summary *out) {
    SumError status = SUM_MEMORY;
    int *sorted = malloc((size_t)(n > 0 ? n : 1) * sizeof *sorted);
    int *histogram = calloc(101, sizeof *histogram);
    if (sorted == NULL || histogram == NULL) {
        goto cleanup;
    }
    if (n == 0) {
        status = SUM_EMPTY;
        goto cleanup;
    }
    long long total = 0;
