#include <stdio.h>

typedef enum { OK, TOO_SMALL, TOO_BIG } Check;

static Check check(int x, int *doubled) {
    if (x < 0) {
        return TOO_SMALL;
    }
    if (x > 100) {
        return TOO_BIG;
    }
    *doubled = 2 * x;
    return OK;
}

int main(void) {
    int result = -1;
    int inputs[] = {7, 500, -3};
    for (int i = 0; i < 3; i++) {
        Check c = check(inputs[i], &result);
        printf("%d:%d ", c, result);
    }
    printf("\n");
    return 0;
}
